#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 200005
#define MAXM 200005

typedef struct Edge {
    int to, next;
    long long w;
} Edge;

Edge edges[MAXM * 2];
int head[MAXN];
int edge_cnt = 0;

long long dist[MAXN];
int visited[MAXN];

void add_edge(int u, int v, long long w) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].w = w;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

int dfs(int u, long long val) {
    if (visited[u]) {
        return dist[u] == val;
    }
    visited[u] = 1;
    dist[u] = val;
    for (int i = head[u]; i != -1; i = edges[i].next) {
        int v = edges[i].to;
        long long w = edges[i].w;
        if (!dfs(v, val + w)) {
            return 0;
        }
    }
    return 1;
}

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    memset(head, -1, sizeof(head));
    memset(visited, 0, sizeof(visited));

    for (int i = 0; i < M; i++) {
        int L, R, D;
        scanf("%d %d %d", &L, &R, &D);
        add_edge(L, R, D);
        add_edge(R, L, -D);
    }

    for (int i = 1; i <= N; i++) {
        if (!visited[i]) {
            if (!dfs(i, 0)) {
                printf("No\n");
                return 0;
            }
        }
    }

    printf("Yes\n");
    return 0;
}

