typedef long long ll;

typedef struct Edge {
    int to;
    ll w;
    int next;
} Edge;

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int *head = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) head[i] = -1;

    Edge *edges = (Edge *)malloc((2LL * M) * sizeof(Edge));
    int ecnt = 0;

    for (int i = 0; i < M; i++) {
        int L, R;
        ll D;
        scanf("%d %d %lld", &L, &R, &D);

        edges[ecnt].to = R;
        edges[ecnt].w = D;
        edges[ecnt].next = head[L];
        head[L] = ecnt++;

        edges[ecnt].to = L;
        edges[ecnt].w = -D;
        edges[ecnt].next = head[R];
        head[R] = ecnt++;
    }

    ll *pos = (ll *)malloc((N + 1) * sizeof(ll));
    char *visited = (char *)calloc(N + 1, sizeof(char));
    int *stack = (int *)malloc((N + 1) * sizeof(int));

    for (int s = 1; s <= N; s++) {
        if (visited[s]) continue;

        int top = 0;
        stack[top++] = s;
        visited[s] = 1;
        pos[s] = 0;

        while (top > 0) {
            int v = stack[--top];

            for (int e = head[v]; e != -1; e = edges[e].next) {
                int u = edges[e].to;
                ll expected = pos[v] + edges[e].w;

                if (!visited[u]) {
                    visited[u] = 1;
                    pos[u] = expected;
                    stack[top++] = u;
                } else {
                    if (pos[u] != expected) {
                        printf("No\n");
                        free(head);
                        free(edges);
                        free(pos);
                        free(visited);
                        free(stack);
                        return 0;
                    }
                }
            }
        }
    }

    printf("Yes\n");

    free(head);
    free(edges);
    free(pos);
    free(visited);
    free(stack);
    return 0;
}

