public class Main {
    static int[] parent;
    static long[] rank_arr; // weight: distance from node to its parent (potential difference)
    // weight[i] = x[i] - x[parent[i]]
    static long[] weight;

    static int find(int x) {
        if (parent[x] == x) return x;
        int root = find(parent[x]);
        weight[x] += weight[parent[x]];
        parent[x] = root;
        return root;
    }

    // Returns the weight of x relative to root: x[x] - x[root]
    static long getWeight(int x) {
        find(x); // path compression updates weight[x]
        return weight[x];
    }

    static boolean union(int u, int v, long d) {
        // x[v] - x[u] = d
        // getWeight(u) = x[u] - x[root_u]
        // getWeight(v) = x[v] - x[root_v]
        long wu = getWeight(u);
        long wv = getWeight(v);
        int ru = find(u);
        int rv = find(v);

        if (ru == rv) {
            // Check consistency: x[v] - x[u] should equal d
            // wv - wu should equal d
            return (wv - wu) == d;
        }

        // Merge ru and rv
        // We want: x[v] - x[u] = d
        // wv (x[v] - x[rv]) and wu (x[u] - x[ru])
        // x[v] = wv + x[rv], x[u] = wu + x[ru]
        // x[v] - x[u] = wv + x[rv] - wu - x[ru] = d
        // x[rv] - x[ru] = d + wu - wv
        // So weight[rv] = x[rv] - x[ru] = d + wu - wv (if we attach rv under ru)

        // Use rank for balancing
        if (rank_arr[ru] < rank_arr[rv]) {
            // attach ru under rv
            // weight[ru] = x[ru] - x[rv] = -(d + wu - wv) = wv - wu - d
            parent[ru] = rv;
            weight[ru] = wv - wu - d;
        } else if (rank_arr[ru] > rank_arr[rv]) {
            // attach rv under ru
            // weight[rv] = x[rv] - x[ru] = d + wu - wv
            parent[rv] = ru;
            weight[rv] = d + wu - wv;
        } else {
            parent[rv] = ru;
            weight[rv] = d + wu - wv;
            rank_arr[ru]++;
        }

        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());

        parent = new int[N + 1];
        weight = new long[N + 1];
        rank_arr = new long[N + 1];

        for (int i = 1; i <= N; i++) {
            parent[i] = i;
            weight[i] = 0;
            rank_arr[i] = 0;
        }

        boolean consistent = true;

        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int L = Integer.parseInt(st.nextToken());
            int R = Integer.parseInt(st.nextToken());
            long D = Long.parseLong(st.nextToken());

            if (!union(L, R, D)) {
                consistent = false;
            }
        }

        System.out.println(consistent ? "Yes" : "No");
    }
}

