public class Main {
    static int[] parent;
    static long[] diff; // diff[i] = x[i] - x[parent[i]]

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());

        parent = new int[N + 1];
        diff = new long[N + 1];
        for (int i = 1; i <= N; i++) {
            parent[i] = i;
        }

        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int L = Integer.parseInt(st.nextToken());
            int R = Integer.parseInt(st.nextToken());
            int D = Integer.parseInt(st.nextToken());

            int rootL = find(L);
            int rootR = find(R);

            if (rootL != rootR) {
                // union: attach rootR under rootL
                // x[R] - x[L] = D
                // diff[R] = x[R] - x[rootR]
                // diff[L] = x[L] - x[rootL]
                // We want: x[rootR] = x[L] + D - x[R] + x[rootL]
                // => diff[rootR] = diff[L] + D - diff[R]
                parent[rootR] = rootL;
                diff[rootR] = diff[L] + D - diff[R];
            } else {
                // already connected, check consistency
                if (diff[R] - diff[L] != D) {
                    System.out.println("No");
                    return;
                }
            }
        }
        System.out.println("Yes");
    }

    static int find(int x) {
        if (parent[x] != x) {
            int origParent = parent[x];
            parent[x] = find(parent[x]);
            diff[x] += diff[origParent];
        }
        return parent[x];
    }
}

