public class Main {
    static class Edge {
        int to;
        long diff; // x[to] = x[from] + diff
        Edge(int to, long diff) {
            this.to = to;
            this.diff = diff;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int M = fs.nextInt();

        List<Edge>[] graph = new ArrayList[N];
        for (int i = 0; i < N; i++) graph[i] = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            int l = fs.nextInt() - 1;
            int r = fs.nextInt() - 1;
            long d = fs.nextLong();

            graph[l].add(new Edge(r, d));
            graph[r].add(new Edge(l, -d));
        }

        long[] pos = new long[N];
        boolean[] visited = new boolean[N];

        for (int i = 0; i < N; i++) {
            if (visited[i]) continue;

            Deque<Integer> stack = new ArrayDeque<>();
            stack.push(i);
            visited[i] = true;
            pos[i] = 0;

            while (!stack.isEmpty()) {
                int cur = stack.pop();
                for (Edge e : graph[cur]) {
                    long expected = pos[cur] + e.diff;
                    if (!visited[e.to]) {
                        visited[e.to] = true;
                        pos[e.to] = expected;
                        stack.push(e.to);
                    } else {
                        if (pos[e.to] != expected) {
                            System.out.println("No");
                            return;
                        }
                    }
                }
            }
        }

        System.out.println("Yes");
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

