using namespace std;

struct DSU {
    vector<int> parent, rank_;
    vector<long long> weight; // weight[i] = x[i] - x[parent[i]] (before path compression, x[i] - x[root])

    DSU(int n) : parent(n), rank_(n, 0), weight(n, 0) {
        iota(parent.begin(), parent.end(), 0);
    }

    pair<int, long long> find(int x) {
        if (parent[x] == x) return {x, 0};
        auto [root, w] = find(parent[x]);
        weight[x] += w;
        parent[x] = root;
        return {root, weight[x]};
    }

    // returns false if inconsistent
    bool unite(int l, int r, long long d) {
        // x[r] - x[l] = d
        auto [rootL, wL] = find(l); // wL = x[l] - x[rootL]
        auto [rootR, wR] = find(r); // wR = x[r] - x[rootR]
        if (rootL == rootR) {
            // x[r] - x[l] = wR - wL should equal d
            return (wR - wL == d);
        }
        // merge: set parent of rootR to rootL
        // x[rootR] - x[rootL] = d + wL - wR
        if (rank_[rootL] < rank_[rootR]) {
            // set parent of rootL to rootR
            // x[rootL] - x[rootR] = -(d + wL - wR) = wR - wL - d
            parent[rootL] = rootR;
            weight[rootL] = wR - wL - d;
            if (rank_[rootL] == rank_[rootR]) rank_[rootR]++;
        } else {
            parent[rootR] = rootL;
            weight[rootR] = d + wL - wR;
            if (rank_[rootL] == rank_[rootR]) rank_[rootL]++;
        }
        return true;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    cin >> n >> m;

    DSU dsu(n + 1);
    bool ok = true;

    for (int i = 0; i < m; i++) {
        int l, r;
        long long d;
        cin >> l >> r >> d;
        if (!dsu.unite(l, r, d)) {
            ok = false;
        }
    }

    cout << (ok ? "Yes" : "No") << "\n";

    return 0;
}

