import sys
from collections import defaultdict, deque

def solve():
    input = sys.stdin.readline
    N, M = map(int, input().split())

    graph = defaultdict(list)

    for _ in range(M):
        L, R, D = map(int, input().split())
        graph[L].append((R, D))
        graph[R].append((L, -D))

    dist = {}

    for i in range(1, N + 1):
        if i not in dist:
            dist[i] = 0
            queue = deque([i])
            while queue:
                u = queue.popleft()
                for v, d in graph[u]:
                    if v not in dist:
                        dist[v] = dist[u] + d
                        queue.append(v)
                    else:
                        if dist[v] != dist[u] + d:
                            print("No")
                            return
    print("Yes")

if __name__ == "__main__":
    solve()
